def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Extend each diagonal pair outward, stopping at the grid edge or another color.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue
                for sr, sc, step_r, step_c in (
                    (r, c, -dr, -dc),
                    (nr, nc, dr, dc),
                ):
                    rr, cc = sr + step_r, sc + step_c
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c
    return out
